package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
)

type StructParserOptions struct {
	Filepath string
}

func (opts *StructParserOptions) Parse() (*struct{}, error) {
	file, err := os.Open(opts.Filepath)
	if err != nil {
		return nil, fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	data, err := ioutil.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	var tree ast.ExprStmt
	err = parser.ParseExpr(data, &tree, token.NewFileSet())
	if err != nil {
		return nil, fmt.Errorf("error parsing AST: %w", err)
	}

	structType, ok := tree.X.(*ast.TypeSpec)
	if !ok {
		return nil, fmt.Errorf("expected TypeSpec but got %T", tree.X)
	}

	return structType, nil
}

func main() {
	var opts StructParserOptions
	args := os.Args[1:]

	if len(args) < 2 {
		fmt.Println("Usage: go run script.go filepath structname")
		os.Exit(1)
	}

	opts.Filepath = args[0]
	structName := args[1]

	structType, err := opts.Parse()
	if err != nil {
		log.Fatalf("Error parsing struct: %v", err)
	}

	// Generate the Avro schema
	schema, err := genAvroSchema(structType, structName)
	if err != nil {
		log.Fatalf("Error generating Avro schema: %v", err)
	}

	// Write the schema to a file
	outPath := fmt.Sprintf("%s.avsc", structName)
	f, err := os.Create(outPath)
	if err != nil {
		log.Fatalf("Failed to create output file: %v", err)
	}
	defer f.Close()

	_, err = f.Write([]byte(schema))
	if err != nil {
		log.Fatalf("Failed to write to output file: %v", err)
	}

	fmt.Printf("Generated schema saved to: %s\n", outPath)
}

func genAvroSchema(structType ast.StructType, structName string) ([]byte, error) {
	bsonBytes, err := bson.Marshal(structType)
	if err != nil {
		return nil, fmt.Errorf("error marshaling struct: %w", err)
	}

	jsonStr, err := json.Marshal(bsonBytes)
	if err != nil {
		return nil, fmt.Errorf("error marshaling BSON bytes to JSON: %w", err)
	}

	avroSchema, err := avro.SchemaFromJSON(jsonStr)
	if err != nil {
		return nil, fmt.Errorf("error creating Avro schema from JSON: %w", err)
	}

	return json.Marshal(avroSchema), nil
}
```

