import java.io.File;
import javax.sound.sampled.*;
public class SummerAudio {
    public static void main(String[] args) throws Exception {
        // Load audio files
        AudioInputStream stream = AudioSystem.getAudioInputStream(new File("bird_chirp.wav"));
        AudioFormat format = stream.getFormat();
        DataLine.Info info = new DataLine.Info(SourceDataLine.class, format);
        SourceDataLine line = (SourceDataLine) AudioSystem.getLine(info);
        line.open(format);
        line.start();

        // Play audio files
        playStream(stream, line);

        // Add narration
        String narration = "A warm summer day begins with the sweet melody of bird chirps.";
        playNarration(narration, line);
    }

    private static void playStream(AudioInputStream stream, SourceDataLine line)
            throws LineUnavailableException {
        int bufferLength = 1024;
        byte[] buffer = new byte[bufferLength];
        while (stream.read(buffer) != -1) {
            line.write(buffer, 0, buffer.length);
        }
    }

    private static void playNarration(String narration, SourceDataLine line)
            throws LineUnavailableException {
        String[] words = narration.split("\\s+");
        for (String word : words) {
            line.write(word.getBytes(), 0, word.length());
            line.drain();
            line.stop();
            Thread.sleep(500); // pause for 500ms between words
        }
        line.drain();
        line.stop();
    }
}
